"""Pagina «Oggi»: esercizi da ragionare e ricalcare, scelti in base al tuo punteggio (simile all'Elo degli scacchi).

Ogni esercizio ha:
- un problema (cosa deve fare il programma),
- una domanda sul piano di soluzione (come lo risolveresti) e i passi logici,
- il codice diviso in blocchi; per ogni blocco «cosa fa» (mostrato mentre lo scrivi) e «perché» (dopo).

I seed servono finché Qwen non ne ha preparati altri in sottofondo. Concatenando i blocchi si ottiene un programma che si esegue.
"""

TIERS = {1: "Primi passi", 2: "Base", 3: "Intermedio", 4: "Avanzato", 5: "Da colloquio difficile"}
TIER_DESC = {
    1: "molto facile: un ciclo o una condizione, 6-15 righe in tutto",
    2: "facile: una struttura dati semplice (dizionario, pila, ricerca binaria), 10-22 righe",
    3: "media: tecniche classiche (due puntatori, finestra scorrevole, ordinamenti, memoization), 14-30 righe",
    4: "difficile: strutture dati (liste collegate, alberi, heap, grafi) o programmazione dinamica, 18-40 righe",
    5: "molto difficile: algoritmi da colloquio impegnativo (Dijkstra, backtracking, DP su due dimensioni), 22-45 righe",
}


def tier_rating(t):
    return 650 + 150 * t


def _q(title, tier, problem, plan, steps, blocks, kind="algoritmo"):
    q, options, correct, why = plan
    return {"title": title, "tier": tier, "kind": kind, "problem": problem,
            "plan": {"q": q, "options": options, "correct": correct, "why": why}, "steps": steps,
            "blocks": [{"code": c, "what": w, "explain": e} for c, w, e in blocks]}


